// Comparação técnica (#/comparar/tecnico) — design V3ComparePlan (Planejamento kit):
// editable rules (assumptions), full metric table with margins and origin, exports and a reproducible link.
// Source of truth: this .tsx file (Preact). tecnico.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment } from "../../vendor/preact/preact.module.js";
import { num } from "../../ds/components.js";
import { buildHash } from "../../ds/router.js";
import { Badge, mount } from "../../ds/ui.js";
import { hourlyRows } from "../data.js";
import { METRICS, RULE_DEFAULTS, rulesToQuery } from "../compare.js";
import { loadComparison, SitePickers, fmtMetric } from "./comparar.js";
import { ContextBar, LETTERS, isoHour, download, setQuery } from "./common.js";
const short = (n) => n.replace(/\s*\(.*\)$/, "");
export async function render(outlet, ctx) {
    const { sc, entries, rules, result, live } = await loadComparison(ctx);
    const { rows } = result;
    // editable rules — premissas, never mission requirements
    const field = (key, label, unit) => h("label", { class: "fld" },
        h("span", { class: "lbl-s" }, label + " (" + unit + ")"),
        h("input", { type: "number", min: "0", step: "1", name: key, defaultValue: String(rules[key]), inputMode: "numeric" }),
        h("small", { class: "t3" }, "padrão do protótipo: " + RULE_DEFAULTS[key]));
    const onRules = (e) => {
        e.preventDefault();
        const fd = new FormData(e.currentTarget), r = {};
        for (const k of Object.keys(RULE_DEFAULTS))
            r[k] = Number(fd.get(k));
        setQuery(ctx, rulesToQuery(r));
    };
    const passport = () => ({
        schema: "moonproof.passport.v1",
        generated_utc: new Date().toISOString(),
        link: location.href,
        window: { start_utc: isoHour(sc.t0), days: sc.days, step_minutes: 60 },
        rules: { ...rules, note: "prototype assumptions, not mission requirements" },
        sites: rows.map((r, i) => ({
            letter: LETTERS[i], id: r.id, name: r.name, lat: r.site.lat, lon: r.site.lon, source: r.site.source,
            metrics: r.computed ? Object.fromEntries(METRICS.map(m => [m.key, r.w[m.key]])) : null, battery_margin: "N/D",
            passes_all_rules: r.computed ? r.passAll : null,
            metrics_origin: live ? "POST /api/compare" : "static series", request_sha256: r.w?.request_sha256 || null,
            series_sha256: live ? r.w.series_sha256 : r.series ? r.series.meta.series.sha256 : null, science_status: live ? r.w.science_status : r.series ? r.series.meta.science_status : null,
            provenance: live ? r.w.provenance : r.series ? r.series.meta.provenance : null,
        })),
        disclaimer: "Preliminary, not NASA-reviewed. No flight recommendation.",
    });
    const mval = (r, key) => r.w[key];
    mount(outlet, h(Fragment, null,
        h("div", { class: "page-head" },
            h("div", null,
                h("p", { class: "lbl-s" }, "Kit Planejamento"),
                h("h1", { "data-route-title": "" }, "Compara\u00E7\u00E3o t\u00E9cnica")),
            h(ContextBar, { ctx: ctx, sc: sc, siteSelect: false })),
        h("p", { class: "t3 small", role: "status" }, live ? "API Go ao vivo · métricas preliminares" : "API indisponível para esta janela · métricas da série estática versionada"),
        h(SitePickers, { ctx: ctx, sc: sc, entries: entries }),
        h("form", { class: "solid card rules", "aria-labelledby": "rules-t", onSubmit: onRules },
            h("h2", { class: "h-card", id: "rules-t" }, "Regras (premissas edit\u00E1veis)"),
            h("div", { class: "cards3" },
                field("maxNightH", "Noite máxima", "h"),
                field("maxEarthLossH", "Perda máxima da Terra", "h"),
                field("minSunPct", "Sol visível mínimo", "%")),
            h("p", { class: "t3 small" }, "Altura do mastro, declividade e piso de bateria: N/D nesta vers\u00E3o (n\u00E3o calculados para as s\u00E9ries reais)."),
            h("div", { class: "row wrap" },
                h("button", { type: "submit", class: "btnA" }, "Recalcular"),
                h("button", { type: "button", class: "btnG", onClick: () => setQuery(ctx, rulesToQuery(RULE_DEFAULTS)) }, "Voltar ao padr\u00E3o"))),
        h("section", { class: "solid card tablewrap" },
            h("h2", { class: "h-card" }, "Todas as m\u00E9tricas"),
            h("table", { class: "mtab" },
                h("caption", { class: "sr" }, "Métricas por local na janela de " + sc.days + " dias"),
                h("thead", null,
                    h("tr", null,
                        h("th", { scope: "col" }, "M\u00E9trica"),
                        h("th", { scope: "col" }, "Unid."),
                        rows.map((r, i) => h("th", { scope: "col" }, LETTERS[i] + " · " + short(r.name))),
                        h("th", { scope: "col" }, "Regra"),
                        h("th", { scope: "col" }, "Margem (" + LETTERS.slice(0, rows.length).join(" / ") + ")"),
                        h("th", { scope: "col" }, "Origem"))),
                h("tbody", null,
                    METRICS.map(m => h("tr", null,
                        h("th", { scope: "row" }, m.label),
                        h("td", null, m.unit),
                        rows.map(r => h("td", { class: "num" }, r.computed ? fmtMetric(mval(r, m.key), m.unit) : "N/D")),
                        h("td", null, m.rule ? m.text(rules) : "—"),
                        h("td", { class: "num" }, m.rule ? rows.map(r => { const c = r.checks.find(x => x.key === m.key); return c && Number.isFinite(c.margin) ? (c.margin >= 0 ? "+" : "") + num(c.margin, 0) : "N/D"; }).join(" / ") : "—"),
                        h("td", null,
                            h(Badge, { kind: "est" }),
                            live ? " Go API · LOLA + SPICE" : " série estática · LOLA + SPICE"))),
                    h("tr", null,
                        h("th", { scope: "row" }, "Folga da bateria"),
                        h("td", null, "Wh"),
                        rows.map(() => h("td", null, "N/D")),
                        h("td", null, "\u2014"),
                        h("td", null, "N/D"),
                        h("td", null,
                            h(Badge, { kind: "nd" }),
                            " n\u00E3o calculado")),
                    h("tr", null,
                        h("th", { scope: "row" }, "Altura do relevo"),
                        h("td", null, "m"),
                        rows.map(r => h("td", { class: "num" }, num(r.site.site_height_m, 0))),
                        h("td", null, "\u2014"),
                        h("td", null, "\u2014"),
                        h("td", null,
                            h(Badge, { kind: "est" }),
                            " LOLA LDEM_80S_80M")))),
            h("p", { class: "t3 small" }, "Margem = folga at\u00E9 a regra (positivo atende). Valores da s\u00E9rie hor\u00E1ria LOLA + SPICE, pr\u00E9vios e n\u00E3o revisados pela NASA.")),
        h("section", { class: "solid card" },
            h("h2", { class: "h-card" }, "Exportar e reproduzir"),
            h("div", { class: "row wrap" },
                h("button", { type: "button", class: "btnG", onClick: () => {
                        const lines = ["site,utc,sun_az_deg,sun_el_deg,sun_margin_deg,earth_az_deg,earth_el_deg,earth_margin_deg"];
                        for (const r of rows)
                            if (r.series)
                                for (const row of hourlyRows(r.series, sc.t0, sc.hours))
                                    lines.push(r.id + "," + row.map(x => (typeof x === "number" ? x.toFixed(3) : x)).join(","));
                        download("moonproof_" + isoHour(sc.t0).slice(0, 10) + "_" + sc.days + "d.csv", lines.join("\n"), "text/csv");
                    } }, "CSV hor\u00E1rio (s\u00E9rie est\u00E1tica)"),
                h("button", { type: "button", class: "btnG", onClick: () => download("moonproof_comparacao.json", JSON.stringify({ rules, rows: rows.map(r => ({ id: r.id, w: r.w, checks: r.checks, passAll: r.passAll })) }, null, 2), "application/json") }, "JSON"),
                h("button", { type: "button", class: "btnG", onClick: () => download("moonproof_passaporte.json", JSON.stringify(passport(), null, 2), "application/json") }, "Passaporte")),
            h("label", { class: "fld share" },
                h("span", { class: "lbl-s" }, "Link reproduz\u00EDvel"),
                h("input", { type: "text", readOnly: true, defaultValue: location.href, onFocus: e => e.target.select() })),
            h("button", { type: "button", class: "btnL", onClick: async (e) => {
                    const b = e.currentTarget;
                    try {
                        await navigator.clipboard.writeText(location.href);
                        b.textContent = "Link copiado";
                    }
                    catch {
                        b.textContent = "Copie o link acima";
                    }
                } }, "Copiar link")),
        h("a", { class: "chipg", href: buildHash("/comparar", ctx.query) }, "\u2190 Voltar \u00E0 resposta direta")));
}
